def translate(text: str, language: str) -> str:
    if language == "en" or language not in {"hi", "te", "ta"}:
        return text
    if text in CATALOG:
        return CATALOG[text][language]
    for source in sorted(CATALOG, key=len, reverse=True):
        if source.endswith(".") and text.startswith(source + " "):
            return CATALOG[source][language] + " " + translate(text[len(source) + 1:], language)
    index = ("hi", "te", "ta").index(language)
    for pattern, templates in _TEMPLATES.items():
        match = re.fullmatch(pattern, text)
        if match:
            return templates[index].format(*match.groups())
    # Source-owned financial bases append a bounded missing-cost or accuracy
    # disclosure. Translate only known pieces, never change the captured facts.
    for pattern, templates in _TEMPLATES.items():
        match = re.search(r" (?=" + pattern + r"$)", text)
        if match:
            return translate(text[:match.start()], language) + " " + translate(text[match.end():], language)
    return text
